func checkTransferDependency(file, imported, module string, test bool, stdlib map[string]bool) (bool, string) {
	if strings.HasPrefix(file, "ucupa-core/transport/grpc/internal/transitionwire/") && !test && stdlib[imported] {
		return true, "transfer wire conversion has no standard-library I/O, locks or runtime state"
	}
	// A codec may assemble finite values, never acquire live state, a lock,
	// a database or a connection. Standard-library I/O is not an escape hatch.
	codec := strings.HasPrefix(file, "ucupa-core/internal/store/record/") || strings.HasPrefix(file, "ucupa-core/internal/transfer/encoding/")
	if codec && !strings.HasSuffix(file, "_test.go") && stdlib[imported] {
		switch imported {
		case "crypto/sha256", "encoding/binary", "encoding/hex", "encoding/json", "errors", "slices", "strings":
		default:
			return true, "pure persisted-value codecs cannot perform I/O, own locks or access runtime state"
		}
	}
	if imported == module+"/ucupa-core/transport/grpc/internal/transition" {
		if file == "ucupa-core/transport/grpc/server.go" || file == "ucupa-core/transport/grpc/server_transition_test.go" {
			return true, ""
		}
		return true, "only the Core transport host assembles the transition RPC group; no direct caller or business import"
	}
	if imported == module+"/ucupa-core/internal/transfer" {
		if file == "ucupa-core/instance/instance.go" {
			return true, ""
		}
		return true, "transfer operations are assembled only in Core instance; adapters consume its narrow public port"
	}
	if dependencies, ok := transferDependencies[file]; ok {
		if reviewedDependencyAllowed(imported, module, stdlib, dependencies...) {
			return true, ""
		}
		return true, "transfer uses only its reviewed per-file value, fact or sole-owner codec dependencies; no other owner, workflow or RPC access"
	}
	if codec || strings.HasPrefix(file, "ucupa-core/internal/transfer/") || strings.HasPrefix(file, "ucupa-core/transport/grpc/internal/transition/") || strings.HasPrefix(file, "ucupa-core/transport/grpc/internal/transitionwire/") || strings.HasPrefix(file, "ucupa-core/transport/grpc/transitionconn/") {
		return true, "new transfer source requires an explicit responsibility and dependency review"
	}
	if imported == module+"/ucupa-core/internal/transfer/fact" || strings.HasPrefix(imported, module+"/ucupa-core/internal/transfer/") {
		return true, "transfer facts are consumed only by registered sole-owner capture, control, replay, codec and tests"
	}
	if imported == module+"/ucupa-core/internal/store/record" {
		return true, "persisted value representations are consumed only by registered codecs, commit and format tests"
	}
	if imported == module+"/ucupa-core/transport/grpc/internal/transitionwire" {
		return true, "transfer wire evidence is consumed only by registered authenticated source/receiver adapters and tests"
	}
	return false, ""
}

func transferLocation(file string) (bool, string) {
	if _, ok := transferDependencies[file]; ok {
		return true, ""
	}
	if strings.HasPrefix(file, "ucupa-core/internal/store/record/") || strings.HasPrefix(file, "ucupa-core/internal/transfer/") || strings.HasPrefix(file, "ucupa-core/transport/grpc/internal/transition/") || strings.HasPrefix(file, "ucupa-core/transport/grpc/internal/transitionwire/") || strings.HasPrefix(file, "ucupa-core/transport/grpc/transitionconn/") {
		return true, "new transfer source requires exact responsibility registration"
	}
	return false, ""
}
